(123, 'home_slider_title_1', '[\"\\u0628\\u0644\\u0627\\u062a\\u064a\\u0646\\u064a\\u0648\\u0645 \\u0627\\u0644\\u0634\\u0631\\u0642\\u064a\\u0629 \\u0644\\u0644\\u0625\\u0633\\u062a\\u0642\\u062f\\u0627\\u0645\",\"\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645\",\"\\u062a\\u0648\\u0641\\u0631 \\u0628\\u0644\\u0627\\u062a\\u064a\\u0646\\u064a\\u0648\\u0645 \\u0627\\u0644\\u0634\\u0631\\u0642\\u064a\\u0629\",\"\\u0628\\u0644\\u0627\\u062a\\u064a\\u0646\\u064a\\u0648\\u0645 \\u0627\\u0644\\u0634\\u0631\\u0642\\u064a\\u0629 \\u0644\\u0644\\u0625\\u0633\\u062a\\u0642\\u062f\\u0627\\u0645\"]', '2021-11-07 12:46:02', '2024-10-02 14:03:35'),
(124, 'home_slider_title_2', '[\"\\u0647\\u062f\\u0641\\u0646\\u0627 \\u062a\\u0642\\u062f\\u064a\\u0645 \\u062a\\u062c\\u0631\\u0628\\u0629 \\u0627\\u0633\\u062a\\u0642\\u062f\\u0627\\u0645 \\u0645\\u062b\\u0627\\u0644\\u064a\\u0629 \\u0644\\u0639\\u0645\\u0644\\u0627\\u0626\\u0646\\u0627\",\"\\u0627\\u0628\\u062f\\u0627 \\u062d\\u062c\\u0632\\u0643 \\u0648\\u0627\\u062a\\u0645\\u0645 \\u0627\\u0644\\u0627\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0648\\u0642\\u0639 \\u0627\\u0644\\u0627\\u0644\\u0643\\u062a\\u0631\\u0648\\u0646\\u064a \\u0627\\u0648 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0646\\u0627 \\u0628\\u0648\\u0642\\u062a \\u0648\\u062c\\u064a\\u0632 \\u0648\\u0628\\u062e\\u0637\\u0648\\u0627\\u062a \\u0645\\u062e\\u062a\\u0635\\u0631\\u0629\",\"\\u0623\\u064a\\u062f\\u064a \\u0639\\u0627\\u0645\\u0644\\u0647 \\u0645\\u0645\\u064a\\u0632\\u0647 \\u0645\\u062f\\u0631\\u0628\\u0629 \\u0628\\u0627\\u062d\\u062a\\u0631\\u0627\\u0641\\u064a\\u0629\",\"\\u0623\\u0641\\u0636\\u0644 \\u0645\\u0643\\u062a\\u0628 \\u0627\\u0633\\u062a\\u0642\\u062f\\u0627\\u0645 \\u0644\\u0644\\u0639\\u0645\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0648\\u0627\\u0641\\u062f\\u0629 \\u0628\\u0627\\u0644\\u0633\\u0639\\u0648\\u062f\\u064a\\u0629 \\u0628\\u0645\\u0639\\u0627\\u064a\\u064a\\u0631 \\u062f\\u0648\\u0644\\u064a\\u0629\"]', '2021-11-07 12:46:02', '2024-10-02 14:03:35'),
