(177, 'vise_newuser_tab1_2_steps', '[\"\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0628\\u0645\\u0646\\u0635\\u0629 \\u0645\\u0633\\u0627\\u0646\\u062f \\u0639\\u0646 \\u0637\\u0631\\u064a\\u0642 \\u0627\\u0633\\u0645 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0648\\u0643\\u0644\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0648\\u0631.\",\"\\u0645\\u0646 \\u0627\\u0644\\u0635\\u0641\\u062d\\u0629 \\u0627\\u0644\\u0631\\u0626\\u064a\\u0633\\u064a\\u0629 \\u0644\\u0644\\u0645\\u0646\\u0635\\u0629 \\u0642\\u0645 \\u0628\\u0627\\u062e\\u062a\\u064a\\u0627\\u0631 \\u062e\\u062f\\u0645\\u0629 \\u0637\\u0644\\u0628 \\u062a\\u0623\\u0634\\u064a\\u0631\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629.\",\"\\u0644\\u0625\\u062a\\u0645\\u0627\\u0645 \\u0627\\u0644\\u0637\\u0644\\u0628 \\u0639\\u0644\\u064a\\u0643 \\u062a\\u0633\\u062f\\u064a\\u062f \\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u062a\\u0623\\u0634\\u064a\\u0631\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u064f\\u0642\\u062f\\u0631 \\u0628\\u0646\\u062d\\u0648 2000 \\u0631\\u064a\\u0627\\u0644 \\u0633\\u0639\\u0648\\u062f\\u064a.\",\"\\u0644\\u0627 \\u064a\\u062a\\u0645 \\u0627\\u0644\\u0637\\u0644\\u0628 \\u0625\\u0630\\u0627 \\u062b\\u0628\\u062a \\u0648\\u062c\\u0648\\u062f \\u0623\\u064a \\u0645\\u0646 \\u0627\\u0644\\u0645\\u062e\\u0627\\u0644\\u0641\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u0648\\u0631\\u064a\\u0629.\",\"\\u062b\\u0645 \\u0642\\u0645 \\u0628\\u062a\\u0639\\u0628\\u0626\\u0629 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u062a\\u0623\\u0634\\u064a\\u0631\\u0629 \\u0644\\u0627\\u062e\\u062a\\u064a\\u0627\\u0631 \\u0627\\u0644\\u0639\\u0645\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0646\\u0632\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0623\\u0646\\u0633\\u0628 \\u0644\\u0643\\u060c \\u0648\\u0645\\u0646 \\u0623\\u0647\\u0645 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a: \\u0627\\u0644\\u0645\\u0647\\u0646\\u0629 - \\