INSERT INTO `cv_previous_sponsor` (`id`, `status`, `apper_front`, `cv_id`, `date_worker_returned`, `reason_worker_returned`, `salary_worker_returned`, `date_receipt`, `text_receipt`, `workers_have_residency`, `performing_medical_examination`, `worker_service_type`, `duration_type`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '6', 0, 1, '2024-10-01', NULL, '3', '2024-10-01', 'الى مكتب بلاتنيوم الشرقية للاستقدام وأمل من المكتب حل مشكلتها وذلك بنقل خدماتها  لتعمل عند صاحب عمل آخر او ترحيلها  حسب ما يراه المكتب مناسبا، كما اتعهد بعدم عمل خروج نهائي او بلاغ هروب أو اي اجراء يخص العاملة إلا بموافقة من المكتب، علماً أنه في حالة نقل خدمات العاملة يحق لي استرجاع مستحقاتي وفقاً للعقد الموحد والنظام الصادر من وزارة الموارد البشرية والتنمية الاجتماعية ، حيث انه حسب التعميم الصادر من مساند والذي ينص على الزام ارجاع المبالغ المستحقة للعملاء من خلال منصة مساند وليس عن طريق حساب المكتب المستقدم وعلى ان يكون ارجاع المبلغ خلال عشرين يوم عمل من تاريخ تسليم العاملة .', '1', '1', '1', NULL, '2024-12-31 10:44:23', '2024-12-31 11:44:23', '2024-12-31 11:44:23'),
