INSERT INTO `frequently_questioned` (`id`, `question`, `answer`, `created_at`, `updated_at`) VALUES
(4, 'كيف يتم استخراج التأشيرة ؟', '<p>1- فتح حساب في مساند</p><p>\r\n2- ادخل حسابي</p><p>\r\n3- لوحة التحكم\r\n</p><p>4- اصدار تأشيرة</p><p>\r\n5- تأشيرة عاملة منزلية\r\n</p><p>6- الجنسية (كينيا –نيروبي)</p>', '2022-03-30 13:55:43', '2022-03-30 15:55:43'),
(5, 'كم مدة استخراج التأشيرة؟', 'خلال 24 ساعة.', '2022-03-29 16:23:58', '2022-03-29 16:23:58'),
(6, 'ماهي الأوراق المطلوبة للاستقدام؟', '<p>1- التأشيرة\r\n</p><p>2- بطاقة الأحوال\r\n</p><p>3- الرقم المربوط بابشر</p><p>\r\n4- اختيار السيفي المناسب لربط العقد.</p>', '2022-03-30 13:57:42', '2022-03-30 15:57:42'),
(7, 'كيفية التسجيل في الموقع ؟', '<p>1- ادخال الاسم\r\n</p><p>2- ادخال رقم الهاتف\r\n</p><p>3- الرقم السري وتأكيده</p>', '2022-03-30 13:58:01', '2022-03-30 15:58:01'),
(8, 'ماهي أسباب رفض إصدار تأشيرة؟', '<p>1- المخالفات\r\n</p><p>2- تجاوز الحد في العدد المسموح به\r\n</p><p>3- إيقاف الخدمات</p><p>\r\n4- عدم سداد الرسوم</p>', '2022-03-30 13:58:18', '2022-03-30 15:58:18'),
(9, 'ماهي الدول المسموح الاستقدام منها للعمالة المنزلية ؟', '<p>1- كينيا </p><p>\r\n2- بنجلاديش</p>', '2022-03-30 13:59:02', '2022-03-30 15:59:02'),
(10, 'ما هي المهن المتاحة لاستقدام العمالة المنزلية ؟', '<p>1- عاملة\r\n</p><p>2- طباخة\r\n</p><p>3- مربية</p>', '2022-03-30 13:59:18', '2022-03-30 15:59:18'),
(11, 'ما هي خطوات تسجيل طلب الاستقدام ؟', '<p>1-اختيار السيرة الذاتية</p><p>\r\n2- تفعيل حساب للعميل</p><p> \r\n3- اختيار المندوب</p><p>\r\n4- التواصل مع المندوب</p>', '2022-03-30 13:59:44', '2022-03-30 15:59:44'),
(12, 'كم من الوقت تستغرقه عملية الاستقدام ؟', '25 يوم الى 60 يوم كحد اقصى.', '2022-03-29 16:34:17', '2022-03-29 16:34:17'),
(14, 'كيف تتم عملية تسليم العاملة ؟', 'في المكتب المحلي واذا كان العميل خارج الرياض او جدة يتم حجز تذكرة للعاملة.', '2022-03-29 16:34:46', '2022-03-29 16:34:46'),
(15, 'كيف ومتى تستلم العاملة راتبها ؟', 'في وقت تحدده الاسرة او العاملة يتم تحويلة عن طريق stc pay', '2022-03-29 16:35:21', '2022-03-29 16:35:21'),
(16, 'ما الحد الأقصى لاستقدام العمالة ؟', '4', '2022-03-29 16:35:40', '2022-03-29 16:35:40'),
(17, 'هل من الممكن للمقيم استقدام عمالة ؟', 'نعم', '2022-03-29 16:36:07', '2022-03-29 16:36:07'),
(18, 'هل يُسمح للعمالة بالسفر مع العميل ؟', 'نعم', '2022-03-29 16:36:31', '2022-03-29 16:36:31'),
(19, 'هل يُمكن تجديد العقد ؟', 'نعم , يتاح للعميل تجديد العقد فور انتهائه.', '2022-03-29 16:37:03', '2022-03-29 16:37:03'),
(20, 'ما هي طرق السداد المتاحة ؟', 'عن طريق مساند', '2022-03-29 13:42:33', '2022-03-29 16:42:33'),
(21, 'ما هي الأسس العلمية والعملية التي يتم على أساسها اختيار العمالة؟', '<p>1-مستوى التعليم</p><p>\r\n2-الكفاءة والخبرة</p><p>\r\n3-الصحة البدنية\r\n</p><p>4-العمر</p>', '2022-03-30 14:00:16', '2022-03-30 16:00:16'),
(22, 'ما هي التكلفة المقدرة لاستقدام العمالة المنزلية؟', '13 الف شاملة الحجر والضريبة المضافة .', '2022-03-29 16:38:40', '2022-03-29 16:38:40'),
(23, 'كم مدة حجز السيفي بالموقع ؟', '48 ساعة.', '2022-03-29 16:39:00', '2022-03-29 16:39:00'),
(24, 'طريقة استخراج تأشيرة التأهيل ؟', 'عن طريق مكتب العمل', '2022-03-29 16:39:24', '2022-03-29 16:39:24'),
(25, 'هل إيقاف الخدمات يعيق استخراج التأشيرة ؟', 'نعم', '2022-03-29 16:39:47', '2022-03-29 16:39:47'),
(26, 'هل المسجلين في الضمان الاجتماعي تأشيرتهم مجانية ؟', 'نعم', '2022-03-29 16:40:11', '2022-03-29 16:40:11');
