INSERT INTO `jobs` (`id`, `title`, `location`, `requirements`, `tasks`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'منسق التدريب والتأهيل (العمالة المنزلية )', 'الرياض', 'خبرة من 3 - 5 سنوات,اللغة الانجليزية - جيد جدا,مؤهل تعليمي معتمد,القدرة علي الاتصال والتواصل مع الجنسيات الاخري,اللباقة وسرعة البديهة', 'وضع الخطط والبرامج والبرامج المناسبة للتاهيل وتدريب العمالة المنزلية حين وصولها,المحافظة علي قائمة مسير بأسماء العاملات المنخرطات في برنامج التدريب والتأهيل وابداء الملاحظات,وضع برنامج اعادة التاهيل العملات المنزليات العائدة الي سوق العمل,رفع تقرير بعد انتهاء برنامج اعادة التاهيل للعاملات المنزليات لتزكية من سيعود الي العمل مرة اخري,رفع تقارير دورية عن وضع برنامج التدريب والتاهيل', 0, '2022-07-17 16:19:55', '2022-07-22 22:41:40'),
(2, 'محاسب', 'الرياض', 'بكالوريس محاسبة,خبرة عملية لاتقل عن 5 سنوات,معرفة تامة بالمبادئ الحسابية,معرفة جيدة باستخدام البرامج المحاسبية المتداولة,معرفة جيدة باللغة الانجليزية,مهارات شخصية وادارية عالية', 'القيام بتسجيل وتصنيف وتلخيص العمليات التجارية ذات الصفة المالية واستخلاص النتائج منها,تحليل النتائج وتقديمها علي شكل تقارير متنوعة تستعملها الادارة في اتخاذ القرارات', 0, '2022-07-22 22:53:42', '2022-07-22 22:53:42'),
(3, 'موظفة خدمة عملاء', 'الرياض', 'علي دراية بمجال الاستقدام,لديه خبرة في استخدام التكنولوجيا والإنترنت وكافة الموارد الأخرى التي تمكنه من تنفيذ مهامه,يجب أن يكون الشخص مدربا جيدا على طرق التواصل الفعالة وكيفية الرد على العملاء وفن التعامل معهم.', 'القيام باستقبال الزوار والترحيب بهم ومساعدتهم في الوصول لأقرب موظف يمكنه خدمته,تنظيم المكالمات الصادرة والوارده من والي الشركة', 1, '2022-07-23 17:00:10', '2022-07-30 10:08:12'),
(5, 'مسئول علاقات حكومية', 'الرياض', 'يتطلب خبرة سابقة في هذا المجال,لديه مؤهل ثانوي علي لاقل', 'قيام مسئول العلاقات الحكومية بجميع معاملات الشركة والعملاء الي تخص الدوار الحكومية,القيام بعمالات الرسمية من سفارات وقنصليات وغيرها ذات الطابع الحكومي والرسمي', 0, '2022-07-23 17:06:38', '2022-07-23 17:11:13'),
(6, 'مترجم / مترجمة', 'الرياض', 'لديه درجة البكالوريس في الترجمة اومجال مشابه او مؤهل معتمد,حاصل علي تدريبات متخصصة في مجالات الترجمة,خبرة عملية في هذا المجال', 'ترجمة النصوص والترجمة الفورية للانشطة المطلوبة للشركة,الترجمة الفورية لجمهور العملاء للتاكد من تلبية الاحتاجيات ووصول الخدمة وتقديمها بالصور المناسبة والمرضية للعملاء', 0, '2022-07-23 17:10:06', '2022-07-23 17:10:06'),
(8, 'سكرتير / سكرتيرة', 'الرياض', '', '', 0, '2022-07-30 10:01:23', '2022-07-30 10:01:23'),
(9, 'مشرف / مشرفة السكن والايواء', 'الرياض', '', '', 1, '2022-07-30 10:04:01', '2022-07-30 10:04:01'),
(10, 'مسؤول خدمات تعاقدية', 'الرياض', '', '', 1, '2022-07-30 10:05:08', '2022-07-30 10:05:08'),
(11, 'أخصائي توظيف', 'الرياض', '', '', 1, '2022-07-30 10:05:24', '2022-07-30 10:05:24'),
(12, 'مسؤول الرواتب والحوافز والاجازات', 'الرياض', '', '', 1, '2022-07-30 10:05:57', '2022-07-30 10:05:57'),
(13, 'أخصائي تدريب وتطوير', 'الرياض', '', '', 1, '2022-07-30 10:06:15', '2022-07-30 10:06:15'),
