(17, 'أخصائي تسويق', 'الرياض', '', '', 1, '2022-07-30 10:07:28', '2022-07-30 10:07:28'),
(18, 'أخصائي علاقات عامة', 'الرياض', '', '', 1, '2022-07-30 10:07:43', '2022-07-30 10:07:43'),
(19, 'مسؤول علاقات عملاء', 'الرياض', '', '', 1, '2022-07-30 10:08:55', '2022-07-30 10:08:55'),
(20, 'مدير فني تقنية', 'الرياض', '', '', 1, '2022-07-30 10:09:12', '2022-07-30 10:09:24'),
