INSERT INTO `lodging_notes` (`id`, `cv_sponsor_id`, `note`, `added_by`, `created_at`, `updated_at`) VALUES
(1, 1, 'الى مكتب بلاتنيوم الشرقية للاستقدام وأمل من المكتب حل مشكلتها وذلك بنقل خدماتها  لتعمل عند صاحب عمل آخر او ترحيلها  حسب ما يراه المكتب مناسبا، كما اتعهد بعدم عمل خروج نهائي او بلاغ هروب أو اي اجراء يخص العاملة إلا بموافقة من المكتب، علماً أنه في حالة نقل خدمات العاملة يحق لي استرجاع مستحقاتي وفقاً للعقد الموحد والنظام الصادر من وزارة الموارد البشرية والتنمية الاجتماعية ، حيث انه حسب التعميم الصادر من مساند والذي ينص على الزام ارجاع المبالغ المستحقة للعملاء من خلال منصة مساند وليس عن طريق حساب المكتب المستقدم وعلى ان يكون ارجاع المبلغ خلال عشرين يوم عمل من تاريخ تسليم العاملة .', 1, '2024-10-01 07:16:11', '2024-10-01 07:16:11'),
