INSERT INTO `recruitment_form` (`id`, `user_id`, `name`, `email`, `phone`, `address`, `iduser`, `visa_id`, `nationality_id`, `occuption_id`, `social_id`, `age_id`, `region_id`, `lang_id`, `exper_id`, `requirement_id`, `is_seen`, `created_at`, `updated_at`) VALUES
(1, 1508, 'روان', NULL, '530062807', NULL, NULL, 0, 100, 5, 1, 2, 5, 1, NULL, NULL, 1, '2024-10-05 22:24:52', '2024-10-06 12:14:58'),
(2, 1517, 'عبدالله علي الدوسري', NULL, '505912299', NULL, NULL, 2147483647, 300, 1, 4, 2, 3, 1, 1, 'شروط الوالده \r\nمسلمة \r\nالعمر من ٣٠ إلى ٣٥ سنة \r\nمتعلمة تجيد القراءة والكتابة\r\nسبق لها العمل في احدى الدول العربية\r\nتجيد فن الطبخ والغسيل والكوي و أعمال النظافة', 1, '2024-10-08 05:53:19', '2024-10-08 09:13:03'),
(3, 1578, 'علي محمدالصاغه', NULL, '555888165', NULL, NULL, 1906263662, 174, 1, 1, 1, 6, 6, 1, NULL, 1, '2024-10-28 14:15:38', '2024-10-28 14:26:29'),
(4, 1594, 'صالح بن سعيد الزهراني', NULL, '554450708', NULL, NULL, 1, 174, 1, 4, 2, 3, 2, 1, 'السلام عليكم\r\nأرغب استقدام عاملة منزلية من الفلبين مسلمة عمرها بين 30-40 سنة سبق لها العمل. ويمكن لها التحدث باللغة العربية أو الانجليزية. وشكراً لكم،،،', 1, '2024-11-03 10:51:39', '2024-11-24 07:36:00'),
(5, 1604, 'باسم علي العبدالوهاب', NULL, '504917106', NULL, NULL, 2147483647, 297, 1, 2, 2, 6, 1, NULL, 'يمكنها مجالسة الاطفال عمر ٢ سنة', 1, '2024-11-04 15:03:09', '2024-11-24 07:35:52'),
(6, 1620, 'عبدالله الغامدي', NULL, '564228778', NULL, NULL, 28775379, 300, 1, 5, 2, 3, 1, 1, NULL, 1, '2024-11-12 08:28:02', '2024-11-24 07:35:47'),
(7, 167, 'Ahmed Nasir Alkhalfan', NULL, '564201000', NULL, NULL, 0, 174, 1, 1, 1, 6, 2, 1, 'شكلٍ جميلة ،مانتكون كبيرة في العمر عندها خبرة في العمل في المنزل', 1, '2024-11-13 17:49:46', '2024-11-24 07:35:39'),
(8, 1635, 'رحاب علي الشلاتي', NULL, '504974240', NULL, NULL, 0, 174, 1, 2, 2, 5, 2, 1, 'رعاية كبار السن', 1, '2024-11-24 12:19:47', '2024-11-24 14:44:42'),
(9, 1648, 'نايف المقرن', NULL, '555457549', NULL, NULL, 30166724, 174, 1, 4, 2, 5, 2, 1, NULL, 1, '2024-12-01 15:54:17', '2024-12-01 15:58:57'),
(10, 1656, 'محمدالعويس', NULL, '555795210', NULL, NULL, 0, 150, 5, 1, 1, 5, 2, NULL, 'مطلوب استقدام سائقة من اوغندا  اذا يوجد سي في  ارسلو', 1, '2024-12-09 07:52:04', '2024-12-09 22:21:04'),
(11, 1667, 'سعيد عبدالله الزهراني', NULL, '555149096', NULL, NULL, 1906760636, 174, 1, 3, 2, 5, 2, 1, NULL, 1, '2024-12-15 16:19:08', '2024-12-16 16:14:15'),
(12, 1705, 'Ali Althenayan', NULL, '548820063', NULL, NULL, 1906794496, 100, 5, 2, 2, 5, 2, 1, NULL, 1, '2024-12-29 16:25:30', '2024-12-29 18:37:56'),
(13, 1706, 'Maria Alnattar', NULL, '544787800', NULL, NULL, 0, 174, 1, 1, 2, 3, 2, NULL, 'العناية بالاطفال', 1, '2024-12-30 10:03:26', '2024-12-31 09:01:13'),
(14, 1717, 'إحسان البيات', NULL, '560636670', NULL, NULL, 0, 150, 1, 3, 1, 3, 2, 2, NULL, 1, '2025-01-05 20:24:06', '2025-01-06 08:45:15'),
(15, 1758, 'عبدالرؤوف عبدالمحسن الرسن', NULL, '555822669', NULL, NULL, 2147483647, 174, 1, 3, 1, 4, 2, 2, '1- تتمتع  بإجازتها يوم واحد اسبوعياً  في غير الويكند وتقضيها داخل المنزل\r\n2- يمنع استخدام الجوال اثناء وقت العمل وتستخدمه في غرفتها فقط\r\nالعمل: مدينة الدمام', 1, '2025-01-28 08:45:59', '2025-01-28 09:47:50'),
(16, 952, 'فداء المرهون', NULL, '530059928', NULL, NULL, 1, 174, 1, 4, 2, 5, 1, 1, 'لديها الخبرة والمقدرة على العمل', 1, '2025-01-30 17:12:09', '2025-01-30 17:25:43'),
(17, 331, 'عبيد فضيان الحربي', NULL, '501243464', NULL, NULL, 0, 174, 1, 4, 2, 6, 2, 1, 'خبرة سابقة بالخليج ، خبرة بالطبخ، تقبل مساعدة الوالدة في اهتمامتها الزراعية المنزلية.\r\n\r\nالمنزل لايوجد فيه اطفال ماعدا في بعض المناسبات\r\n\r\nالمنزل في الظهران', 1, '2025-02-09 20:32:50', '2025-02-11 18:09:13'),
(18, 1795, 'Amirah', NULL, '531870242', NULL, NULL, 0, 174, 1, 2, 1, 5, 2, 2, 'ابي المواصفات التالية \r\nفلبينية عمر ٢٨ - ٣٣\r\nالإنجليزي ممتاز جدا\r\nشكلها مقبول \r\nتحب تتعامل مع الأطفال وتجالسهم \r\nتعرف تطبخ وتكوي وتنظف وتسوي اشغال البيت\r\nماتتكلم كثير \r\nليس لديها إلا طفل أو طفلين أو بدون أطفال\r\nتكمل العقد كامل معاية\r\nتعاملها راقي جدا \r\nوليس لديها اضطرابات نفسية', 1, '2025-02-14 19:35:15', '2025-02-16 12:22:58'),
(19, 1805, 'نايف عبدالعزيزالعرفج', NULL, '550249099', NULL, NULL, 0, 174, 1, 3, 2, 6, 1, 1, 'خبرة في التعامل مع الاطفال الرضع و تتعامل مع الاطفال', 1, '2025-02-17 18:11:09', '2025-02-17 20:04:19'),
(20, 1820, 'بدريه مسيفر ساير القثامي', NULL, '548310827', NULL, NULL, 31152602, 300, 1, 3, 2, 6, 1, 2, NULL, 1, '2025-02-26 11:22:11', '2025-02-26 13:53:06'),
(21, 1827, 'رحاب محمود الأنصاري', NULL, '503940985', NULL, NULL, 1906964324, 150, 1, 3, 1, 3, 2, 1, NULL, 1, '2025-03-08 01:51:14', '2025-03-10 00:08:57'),
(22, 1827, 'رحاب محمود محمد الأنصاري', NULL, '503940985', NULL, NULL, 1906964324, 150, 1, 3, 1, 3, 2, 1, 'مذكور في الڤيزا ان العامله من اوغنده/  كمبالا لم أجد اسم المدينة في الاختيارات', 1, '2025-03-08 01:55:27', '2025-03-10 00:09:04'),
(23, 1858, 'حنان شبير', NULL, '566138019', NULL, NULL, 1906601371, 174, 1, 3, 1, 5, 2, 1, '*مواصفات العاملة*\r\n\r\n1- الجنسية: فلبينية \r\n2- العمر: 26-36\r\n3- بلد المنشأ: مدينة وليست قرية\r\n4- التعليم: يفضل جامعية بحد اقصى ثانوية\r\n5- اللغات: تتحدث الانجليزية بطلاقة \r\n6- الخبرات: سبق لها العمل بالسعودية \r\n7- المهارات: الطبخ والاهتمام بالاطفال والتنظيف والكي \r\n8- تفضيلات أخرى: ليس لديها اطفال او اطفال كبار بالعمر', 1, '2025-03-17 23:38:39', '2025-03-18 19:19:41'),
(24, 1859, 'عبدالعزيز عطية', NULL, '537400402', NULL, NULL, 0, 174, 1, 1, 2, 4, 2, 1, 'السلام عليكم - ارغب في التعاقد مع عاملة منزلية ينتهي عقدها قريبا الشهر القادم اسمها- P6788439B  Evangelyn Mojica كانت قادمه لعاىله من مكتبكم في الشرقية. اذا كانت هناك طريقة للتعاقد معها بعد انتهاء عقدها الرجاء ابلاغي. المدينة سانتياغو- الدولة الفلبين. هي داخل السعودية الان ولكن لتسريع الاجراءات اتمنى ان نبدا الان. شكرا لكم', 1, '2025-03-18 02:15:21', '2025-03-18 19:26:56'),
(25, 1155, 'وضحى فهيد القحطاني', NULL, '534306333', NULL, NULL, 2147483647, 174, 1, 3, 2, 5, 2, 1, 'لأيهم إذا كانت عازبه أو متزوجه\r\nولكن أريد لديها خبره وتعرف تطبخ', 1, '2025-03-18 09:59:49', '2025-03-18 19:35:17'),
(26, 1866, 'نوف عبدالكريم', NULL, '565778883', NULL, NULL, 31262245, 174, 1, 1, 2, 3, 2, 1, 'تجيد وترغب التعامل مع الاطفال', 1, '2025-03-20 11:02:03', '2025-03-20 18:15:17'),
(27, 1442, 'Salah Alali', NULL, '551379000', NULL, NULL, 0, 113, 1, 1, 1, 5, 2, NULL, 'يجب ان تكون  العامله من العاصمه وتتقن اللغة الانجليزيه', 1, '2025-03-27 12:19:20', '2025-03-27 23:29:08'),
(28, 1890, 'Faisal Al Modlij', NULL, '565000333', NULL, NULL, 1907007804, 174, 1, 2, 2, 4, 1, 1, 'وجود خبرة سابقة وتتحدث اللغة العربية', 1, '2025-04-05 05:06:47', '2025-04-06 10:35:06'),
